"""Locate and validate the CrisisBench v1.0 English humanitarian split files.

Order of attempts (cheapest first):
  1. already-unpacked files in the workspace ``data/raw``;
  2. shared download cache (``REPRO_DATA_CACHE``) - either the three TSVs or the
     official ``crisis_datasets_benchmarks_v1.0.tar.gz`` archive;
  3. network mirrors (Hugging Face mirror of the official v1.0 tree, then the
     QCRI data host).

Writes ``data/manifest.json`` with source, sha256 and detected columns and
raises ``AcquisitionError`` if no candidate satisfies the published split
sizes and label count.
"""
from __future__ import annotations

import hashlib
import json
import os
import shutil
import sys
import tarfile
import time

import pandas as pd

if __package__ in (None, ""):
    sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from src import config

HF_MIRROR = (
    "https://huggingface.co/datasets/timhigins/crisisbench/resolve/main/"
    "data/all_data_en/{fname}"
)
OFFICIAL_TARBALLS = [
    "https://data.crisisnlp.org/crisis_datasets_benchmarks_v1.0.tar.gz",
    "http://data.crisisnlp.org/crisis_datasets_benchmarks_v1.0.tar.gz",
]
TARBALL_NAME = "crisis_datasets_benchmarks_v1.0.tar.gz"


class AcquisitionError(RuntimeError):
    pass


def _sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _split_paths(raw_dir: str) -> dict[str, str]:
    return {s: os.path.join(raw_dir, config.SPLIT_FILES[s]) for s in ("train", "dev", "test")}


def _have_all(paths: dict[str, str]) -> bool:
    return all(os.path.isfile(p) and os.path.getsize(p) > 0 for p in paths.values())


def _extract_from_tarball(tar_path: str, out_dir: str) -> dict[str, str]:
    """Extract only the three humanitarian English TSVs from the v1.0 archive."""
    wanted = {config.SPLIT_FILES[s]: s for s in ("train", "dev", "test")}
    got: dict[str, str] = {}
    with tarfile.open(tar_path, "r:gz") as tf:
        for member in tf.getmembers():
            base = os.path.basename(member.name)
            if member.isfile() and base in wanted:
                src = tf.extractfile(member)
                if src is None:
                    continue
                dst = os.path.join(out_dir, base)
                with open(dst, "wb") as out:
                    shutil.copyfileobj(src, out)
                got[wanted[base]] = dst
    return got


def _download_file(url: str, dst: str, timeout: int = 300) -> str:
    import requests

    tmp = dst + ".part"
    with requests.get(url, timeout=timeout, stream=True, allow_redirects=True) as r:
        r.raise_for_status()
        with open(tmp, "wb") as fh:
            for chunk in r.iter_content(chunk_size=1 << 20):
                fh.write(chunk)
    shutil.move(tmp, dst)
    return dst


def _try_cache(raw_dir: str, log) -> bool:
    cache = config.CACHE_DIR
    if not cache or not os.path.isdir(cache):
        return False
    paths = _split_paths(raw_dir)
    # (a) pre-unpacked TSVs anywhere in the cache
    for root, _dirs, files in os.walk(cache):
        for split, fname in config.SPLIT_FILES.items():
            if fname in files and not os.path.isfile(paths[split]):
                src = os.path.join(root, fname)
                log(f"cache hit: {src}")
                shutil.copyfile(src, paths[split])
        if _have_all(paths):
            return True
    # (b) the official tarball in the cache
    for root, _dirs, files in os.walk(cache):
        if TARBALL_NAME in files:
            tp = os.path.join(root, TARBALL_NAME)
            log(f"cache tarball: {tp}")
            got = _extract_from_tarball(tp, raw_dir)
            if _have_all(_split_paths(raw_dir)):
                return True
    return False


def acquire(raw_dir: str | None = None, log=print, allow_download: bool = True) -> dict:
    """Return the manifest dict; raise AcquisitionError on failure."""
    raw_dir = raw_dir or config.RAW_DIR
    os.makedirs(raw_dir, exist_ok=True)
    os.makedirs(config.PROCESSED_DIR, exist_ok=True)
    paths = _split_paths(raw_dir)
    source = None

    if _have_all(paths):
        source = "workspace data/raw (pre-existing)"
    elif _try_cache(raw_dir, log) and _have_all(paths):
        source = "REPRO_DATA_CACHE"
    elif allow_download:
        for url in [HF_MIRROR.format(fname=config.SPLIT_FILES[s]) for s in ("train", "dev", "test")]:
