                _download_file(HF_MIRROR.format(fname=config.SPLIT_FILES[split]), paths[split])
                log(f"  downloaded {split}")
            source = f"HF mirror: {HF_MIRROR}"
        except Exception as exc:  # noqa: BLE001
            log(f"  HF mirror failed: {type(exc).__name__}: {exc}")
        if not _have_all(paths):
            for url in OFFICIAL_TARBALLS:
