"""Data loading, column mapping, leakage guards and the cyclone subsets."""
from __future__ import annotations

import os
import re
import sys
from dataclasses import dataclass, field

import pandas as pd

if __package__ in (None, ""):
    sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from src import config
from src.preprocess import clean_column


@dataclass
class CrisisData:
    train: pd.DataFrame
    dev: pd.DataFrame
    test: pd.DataFrame
    text_col: str
    label_col: str
    event_col: str | None
    labels: list[str] = field(default_factory=list)
    notes: dict = field(default_factory=dict)

    @property
    def train_dev(self) -> pd.DataFrame:
        return pd.concat([self.train, self.dev], ignore_index=True)


def _pick(columns: list[str], candidates: list[str], what: str) -> str:
    for c in candidates:
        if c in columns:
            return c
    raise ValueError(f"none of {candidates} present among columns {columns} (needed for {what})")


def load_splits(raw_dir: str | None = None, log=print) -> CrisisData:
    raw_dir = raw_dir or config.RAW_DIR
    frames = {}
    for split, fname in config.SPLIT_FILES.items():
        path = os.path.join(raw_dir, fname)
        df = pd.read_csv(path, sep="\t", dtype=str, keep_default_na=False)
        df[config.LABEL_COLUMN_CANDIDATES[0]] = df[config.LABEL_COLUMN_CANDIDATES[0]].astype(str).str.strip()
        frames[split] = df

    ref = frames["train"]
    text_col = _pick(list(ref.columns), config.TEXT_COLUMN_CANDIDATES, "model input")
    label_col = _pick(list(ref.columns), config.LABEL_COLUMN_CANDIDATES, "class label")
    event_col = next((c for c in config.EVENT_COLUMN_CANDIDATES if c in ref.columns), None)

    notes = {}
    if text_col == "text_clean":
        # A released clean column exists; still derive a normalised copy so the
        # stated conservative preprocessing is what the model sees (R3).
        notes["released_text_clean"] = True
        src_col = "text_clean"
    else:
        src_col = text_col
    for split, df in frames.items():
        df["text_clean_final"] = clean_column(df[src_col])
        df["label"] = df[label_col]

    labels = sorted(set().union(*[set(df["label"].unique()) for df in frames.values()]))
    if len(labels) != config.EXPECTED_NUM_LABELS:
        raise ValueError(f"expected {config.EXPECTED_NUM_LABELS} labels, found {len(labels)}: {labels}")
    for split, df in frames.items():
        missing = set(df["label"].unique()) - set(labels)
        if missing:
            raise ValueError(f"{split} has labels outside the union: {missing}")

    data = CrisisData(train=frames["train"], dev=frames["dev"], test=frames["test"],
                      text_col=text_col, label_col=label_col, event_col=event_col,
                      labels=labels, notes=notes)
    _size_checks(data, log)
    _leakage_guard(data)
    _text_checks(data, log)
    return data


def _size_checks(data: CrisisData, log) -> None:
    got = {"train": len(data.train), "dev": len(data.dev), "test": len(data.test)}
    got["train_plus_dev"] = got["train"] + got["dev"]
    got["total"] = sum(v for k, v in got.items() if k in ("train", "dev", "test"))
    for k, v in config.EXPECTED_SIZES.items():
        if got.get(k) != v:
            raise ValueError(f"split size mismatch for {k}: got {got.get(k)}, expected {v}")
    log(f"split sizes OK: {got}")


def _leakage_guard(data: CrisisData) -> None:
    """R2: only text_clean may enter the feature matrix."""
    feature_frame = data.train[["text_clean_final"]]
    for bad in config.FORBIDDEN_FEATURE_COLUMNS:
        assert bad not in feature_frame.columns, f"forbidden column {bad} in feature frame"


def _text_checks(data: CrisisData, log) -> None:
    for split, df in (("train", data.train), ("dev", data.dev), ("test", data.test)):
        tc = df["text_clean_final"]
        n_empty = int((tc.str.len() == 0).sum())
        if tc.isna().any():
            raise ValueError(f"{split}: NaN in text_clean")
        frac = n_empty / len(df)
        if frac >= 0.01:
            raise ValueError(f"{split}: {frac:.3f} empty texts (>= 1%)")
        mean_tokens = tc.str.split().str.len().mean()
        p95 = tc.str.split().str.len().quantile(0.95)
        log(f"{split}: empty={n_empty} ({frac:.4f}) mean_tokens={mean_tokens:.1f} p95_tokens={p95:.0f}")
        if not (3 <= mean_tokens <= 60):
            log(f"WARNING: {split} mean token count {mean_tokens:.1f} outside plausible short-text range")


# --------------------------------------------------------------------------
# tropical-cyclone subsets (R13, A11)
# --------------------------------------------------------------------------
def cyclone_mask(df: pd.DataFrame, pattern: re.Pattern) -> pd.Series:
    if df.get("event_col") is not None:
        pass
    col = "event" if "event" in df.columns else ("event_name" if "event_name" in df.columns else None)
    if col is None:
        raise ValueError("no event column available for the cyclone subset")
    return df[col].fillna("").astype(str).str.contains(pattern, regex=True)


def cyclone_counts(data: CrisisData, log=print) -> dict:
    trdev = data.train_dev
    out = {}
    for name, pat in (("broad", config.CYCLONE_BROAD_RE), ("strict", config.CYCLONE_STRICT_RE)):
        m_td = cyclone_mask(trdev, pat)
        m_te = cyclone_mask(data.test, pat)
        out[f"{name}_train_dev"] = int(m_td.sum())
        out[f"{name}_test"] = int(m_te.sum())
        out[f"{name}_total"] = int(m_td.sum() + m_te.sum())
        out[f"{name}_events"] = sorted(trdev.loc[m_td, "event"].unique().tolist())
    for key, exp in config.EXPECTED_CYCLONE.items():
        status = "OK" if out.get(key) == exp else f"MISMATCH (expected {exp})"
        log(f"cyclone {key}: {out.get(key)} {status}")
    return out

